INSERT OR IGNORE INTO users(id,created_at) VALUES('demo-owner',1),('demo-sponsor',1);
INSERT OR IGNORE INTO needs(id,owner_id,status,demo,data,private_data,created_at,updated_at,accept_by,recurring_days,received_at,feedback,completed_at) VALUES('demo-birthday','demo-owner','completed',1,'{"title":"一起过生日，也一起吃顿饭","story":"有的生日，是一个人吹蜡烛；有的生日，是一整间教室一起许愿。老师们想为这个月过生日的孩子们准备一顿共同的午餐，让每个愿望都被认真听见。\n\n这是一个虚构的乡村小学集体生日场景。每个月，老师重新确认本期人数、餐食与送达安排，才发布下一份需要。","organizer":"乡村小学的老师们（虚构）","scene":"birthday","meals":[{"name":"汉堡、薯条与饮品套餐","quantity":30,"specification":"演示餐单：指定汉堡 1 份、薯条 1 份、饮品 1 杯；真实发布须按可配送菜单核实。"}],"quantity":30,"location":{"name":"乡村小学 · 共享餐桌（虚构）","address":"演示地址 · 不对应真实学校或收货地点","lat":0,"lng":0},"mealAt":1791777600000,"acceptBy":1791770400000,"referenceCents":90000,"referenceAt":1791691200000,"recurringDays":30,"consent":true,"deliveryCheckedAt":1791691200000}','',1791691200000,1791781200000,1791770400000,30,1791777600000,'孩子们把这顿午餐叫作“生日大餐”。我们围坐在一起，唱歌、许愿，也记得谢谢那位没有到场的朋友。（模拟反馈）',1791781200000);
INSERT OR IGNORE INTO attempts(id,need_id,sponsor_id,need_version,state,display_name,created_at,updated_at,lock_until,last_sync) VALUES('demo-birthday-attempt','demo-birthday','demo-sponsor',1,'delivered','星期三的朋友',1791691200000,1791777600000,1791691200000,1791777600000);
INSERT OR IGNORE INTO needs(id,owner_id,status,demo,data,private_data,created_at,updated_at,accept_by,recurring_days,received_at,feedback,completed_at) VALUES('demo-training','demo-owner','completed',1,'{"title":"为学习守护他人的人，加一餐","story":"从按压节奏到包扎练习，一上午的训练，需要专注，也需要一点体力。给学习急救的伙伴们准备好午餐，让他们在休息之后继续练习，带着更扎实的本领回到日常。\n\n这是虚构的急救培训场景，不代表与红十字会或任何真实培训机构的合作。","organizer":"社区急救学习小组（虚构）","scene":"training","meals":[{"name":"鸡肉汉堡与饮品套餐","quantity":24,"specification":"演示餐单：指定鸡肉汉堡 1 份、配餐 1 份、饮品 1 杯；实际份量与商品由发起方确认。"}],"quantity":24,"location":{"name":"社区学习空间（虚构）","address":"演示地址 · 不对应真实培训机构或收货地点","lat":0,"lng":0},"mealAt":1791777600000,"acceptBy":1791770400000,"referenceCents":72000,"referenceAt":1791691200000,"recurringDays":null,"consent":true,"deliveryCheckedAt":1791691200000}','',1791691200000,1791781200000,1791770400000,NULL,1791777600000,'午餐准时摆上桌，大家边吃边交流练习心得。下午又多学会了一种帮助别人的方法。谢谢这份支持。（模拟反馈）',1791781200000);
INSERT OR IGNORE INTO attempts(id,need_id,sponsor_id,need_version,state,display_name,created_at,updated_at,lock_until,last_sync) VALUES('demo-training-attempt','demo-training','demo-sponsor',1,'delivered','一位路过的邻居',1791691200000,1791777600000,1791691200000,1791777600000);
INSERT OR IGNORE INTO needs(id,owner_id,status,demo,data,private_data,created_at,updated_at,accept_by,recurring_days,received_at,feedback,completed_at) VALUES('demo-basketball','demo-owner','completed',1,'{"title":"终场哨响后，我们一起开饭","story":"最后一球落地，输赢有了结果，友谊还在继续。队员、裁判和志愿者忙完决赛，终于可以坐在一起，把赛场上的故事再讲一遍。\n\n这是一份虚构的大学篮球决赛餐食需求。指定的整单餐食由一位赞助人支持，队员收餐后留下赛后反馈与感谢。","organizer":"校园篮球社（虚构）","scene":"basketball","meals":[{"name":"双层汉堡与饮品套餐","quantity":40,"specification":"演示餐单：指定双层汉堡 1 份、薯条 1 份、饮品 1 杯；真实下单不允许赞助人自行替换。"}],"quantity":40,"location":{"name":"大学体育馆旁 · 休息区（虚构）","address":"演示地址 · 不对应真实大学或收货地点","lat":0,"lng":0},"mealAt":1791777600000,"acceptBy":1791770400000,"referenceCents":128000,"referenceAt":1791691200000,"recurringDays":null,"consent":true,"deliveryCheckedAt":1791691200000}','',1791691200000,1791781200000,1791770400000,NULL,1791777600000,'比分定格了，大家还没聊够。这顿饭让两队和志愿者坐到同一张桌前。谢谢校友 7 号，让今天有了一个温暖的结尾。（模拟反馈）',1791781200000);
